function s(v) { return String(v == null ? '' : v).trim(); }
const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

const mine = rows.filter(function (r) { return s(r.investor).toLowerCase().replace(/[^a-z]/g, '') === 'bluegreenventures'; });

let sent = 0, pending = 0, paused = 0;
const detail = mine.map(function (r) {
  const isP = s(r.pause) !== '';
  const sh = s(r.deal_shared).toLowerCase() === 'yes';
  if (isP) { paused++; } else if (sh) { sent++; } else { pending++; }
  return { deal_id: s(r.deal_id), startup: s(r.startup), owner: s(r.owner),
           state: isP ? 'paused' : (sh ? 'sent' : 'pending'),
           date_shared: s(r.date_shared), next_action: s(r.next_action),
           next_due: s(r.next_due), investor_response: s(r.investor_response),
           notes: s(r.notes) };
});
detail.sort(function (a, b) { return a.deal_id < b.deal_id ? -1 : 1; });

return [{ json: {
  total_pipeline_rows: rows.length,
  bluegreen_rows: mine.length,
  sent: sent, pending: pending, paused: paused,
  startups_sent: detail.filter(function (d) { return d.state === 'sent'; }).map(function (d) { return d.startup; }),
  startups_pending: detail.filter(function (d) { return d.state === 'pending'; }).map(function (d) { return d.startup; }),
  detail: detail
}}];
